import{_ as l,l as o,o as e,c as s,v as t,p as n,x as i,d as m,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"激活：ReLU 与饱和","description":"","frontmatter":{"title":"激活：ReLU 与饱和","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/activation-relu-saturation.md","filePath":"llm/activation-relu-saturation.md","lastUpdated":1789023840000}'),p={name:"llm/activation-relu-saturation.md"};function E(c,a,A,u,L,_){const r=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="激活-relu-与饱和" tabindex="-1">激活：ReLU 与饱和 <a class="header-anchor" href="#激活-relu-与饱和" aria-label="Permalink to &quot;激活：ReLU 与饱和&quot;">​</a></h1><div class="epigraph"><p>逐元素非线性把一串仿射从「仍是一层仿射」里救出来；导数长期接近零，反向增益就被掐断。</p><footer>—— 据 Nair &amp; Hinton, Rectified Linear Units Improve Restricted Boltzmann Machines, ICML 2010；Glorot, Bordes &amp; Bengio, AISTATS 2011 整理</footer></div><p><a href="/llm/linear-layer-bias">线性层与偏置</a>补上 \\(b\\)。本课不重写仿射。缺口是：仿射的复合仍是仿射，再深的 \\(W^{(\\ell)}\\) 也只是一张等效矩阵。必须在层间插入不是仿射的逐元素函数 \\(\\sigma\\)。本课对比饱和激活与 ReLU：前者在幅值大时 \\(\\sigma&#39;\\approx 0\\)，加重消失；后者在正半轴增益为 \\(1\\)，负半轴为 \\(0\\)。GELU、SwiGLU 是后话，这里只把「为何要非线性、饱和如何伤反向」钉住。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两个仿射 \\(A_2(A_1 x)\\) 等于一个仿射。没有 \\(\\sigma\\)，深度不增加函数类，只增加参数化同一超平面的方式。分类、语言建模需要的决策面是弯曲的、分区的。缺口是最小的非线性：每个坐标独立地 \\(\\sigma(z_i)\\)，形状不变，不引入新的轴。</p><p>sigmoid \\(\\sigma(z)=(1+\\mathrm{e}^{-z})^{-1}\\)、tanh 把值挤进有界区间，大 \\(|z|\\) 时导数指数变小——这就是饱和。它曾被当作「概率」或「有界特征」的优点，却与<a href="/llm/vanish-explode-grad">梯度消失与爆炸</a>的增益连乘直接冲突。ReLU \\(\\sigma(z)=\\max(z,0)\\) 正半轴不饱和，负半轴硬切。函数类因此变成分段线性，深度开始真正增加折点数量。</p><h3 id="relu-不是「不会消失」" tabindex="-1">ReLU 不是「不会消失」 <a class="header-anchor" href="#relu-不是「不会消失」" aria-label="Permalink to &quot;ReLU 不是「不会消失」&quot;">​</a></h3><p>负半轴导数为 \\(0\\)，若一个单元对几乎所有样本都为负，它的 \\(W\\) 行收不到梯度，称为死 ReLU。这是另一种消失，只是发生在单元子集上，而不是整层谱半径。学习率过大、偏置过负、输入分布突然偏移，都会制造死单元。Leaky ReLU、GELU 缓解硬零，但不取消「需要非线性」这条。把 ReLU 宣传成消失问题的彻底解决，后课残差与初始化会显得多余。</p><p><span class="marginnote">输出层接 softmax 时，倒数第二层常用 ReLU 或 GELU，而不是再接一个 sigmoid。概率由 softmax 提供；中间层要的是不饱和的增益，不是再做一次单纯形。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>MLP 一层：\\(h=\\sigma(Wx+b)\\)。反向：\\(\\mathrm{d}z=\\mathrm{d}h\\odot\\sigma&#39;(z)\\)。ReLU 的 \\(\\sigma&#39;\\) 是指示函数 \\(\\mathbf{1}_{z\\gt 0}\\)（\\(0\\) 点的次梯度取 \\(0\\) 或 \\(1\\) 均可，实现任意约定）。tanh 的 \\(\\sigma&#39;=1-\\tanh^2 z\\)。堆叠 \\(L\\) 层就有 \\(L\\) 次逐元素门，夹在 \\(L\\) 次仿射之间。本课不讨论宽度如何选，那是参数量课。</p>',11)),(e(),n(h,null,{default:i(()=>[d(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20AFF%5B%22%E4%BB%BF%E5%B0%84%20Wx%20%E5%8A%A0%20b%22%5D%20--%3E%20SIG%5B%22%E9%A5%B1%E5%92%8C%E6%BF%80%E6%B4%BB%22%5D%0A%20%20AFF%20--%3E%20RELU%5B%22ReLU%22%5D%0A%20%20SIG%20--%3E%20SAT%5B%22%E5%A4%A7%E5%B9%85%E5%80%BC%E6%97%B6%E5%AF%BC%E6%95%B0%E8%BF%91%200%22%5D%0A%20%20RELU%20--%3E%20POS%5B%22%E6%AD%A3%E5%8D%8A%E8%BD%B4%E5%A2%9E%E7%9B%8A%201%22%5D%0A%20%20RELU%20--%3E%20DEAD%5B%22%E8%B4%9F%E5%8D%8A%E8%BD%B4%E6%AD%BB%E5%8D%95%E5%85%83%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分段线性网络把 \\(\\mathbb{R}^d\\) 切成多面体，每个多面体内仍是仿射，边界由 ReLU 的过零决定。深度增加折点的组合数，这是表达力来源。饱和激活则把表示压进有界盒子，前向不会爆炸，反向却容易没梯度——前向稳定与反向可训不是同一件事。现代前馈默认非饱和（或弱饱和）激活，把有界性交给后课的 LayerNorm，而不是交给 \\(\\sigma\\) 的值域。</p><p>选择 \\(\\sigma\\) 还改变初始化理论：ReLU 大约一半单元为 \\(0\\)，方差传递与 tanh 不同。下一课专门处理这件事，本课只要求：激活的导数进入增益连乘，选 \\(\\sigma\\) 就是在选默认增益。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 GELU 的积分形式，不写门控线性单元。下一课<a href="/llm/why-init">初始化为何需要</a>假定激活已选定，问 \\(W\\) 的尺度。后课默认：MLP 层是仿射加非饱和逐元素激活；说到饱和，是在诊断消失。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无非线性则多层仿射退化成一层；\\(\\sigma\\) 是深度有意义的前提。</li><li>饱和激活在大幅值时掐断反向增益。</li><li>ReLU 正半轴增益为 \\(1\\)，但死单元是局部消失。</li><li>中间层不要用 sigmoid 来「当概率」，概率留给 softmax。</li><li>出处：Nair &amp; Hinton, ICML 2010；Glorot et al., AISTATS 2011。</li></ul>',7))])}const U=l(p,[["render",E]]);export{f as __pageData,U as default};
